import{z as l,x as n,o,c as A,q as r,j as t,D as e,d as E,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"乱序与 ROB","description":"","frontmatter":{"title":"乱序与 ROB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ooo-rob.md","filePath":"cs/ooo-rob.md","lastUpdated":1791063341000}'),d={name:"cs/ooo-rob.md"};function p(c,a,_,R,h,m){const s=n("Mermaid");return o(),A("div",null,[a[2]||(a[2]=r('<h1 id="乱序与-rob" tabindex="-1">乱序与 ROB <a class="header-anchor" href="#乱序与-rob" aria-label="Permalink to &quot;乱序与 ROB&quot;">​</a></h1><div class="epigraph"><p>执行可以按操作数就绪的次序，提交必须按程序序；重排序缓冲把尚未提交的写托住。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/superscalar-issue">上一课</a>每拍可发射多条，但仍按程序序：年长指令缺数据，年轻且独立的也过不去。<a href="/cs/superscalar-issue">流水线异常</a>要求提交点上架构状态精确。本课不重讲发射宽度。缺口是：长延迟 load 会堵住发射口，后面不相关的 ALU 闲着。本课只交出乱序执行与 ROB：执行乱序，提交有序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>load 缺失要几十拍。顺序超标量让后续独立 <code>add</code> 也停。若允许 <code>add</code> 先算完，它的写回不能立刻进寄存器堆，否则精确异常会看见「未来」的 <code>x1</code>。缺口不是再加执行单元，而是<strong>把结果停在缓冲里，按取指序提交，异常时丢弃缓冲</strong>。</p><p>WAR/WAW 在乱序下复活：年轻指令先写同一架构寄存器。必须重命名，不能只用五级那种固定 WB。具体唤醒逻辑是下一课 Tomasulo；本课先钉 ROB 与提交纪律。</p><p><span class="marginnote">直觉类比：ROB 像餐厅的出餐排序台——厨师（执行单元）哪道菜先做好就先摆上台，但服务员只按点菜单顺序上桌（提交）。某道菜做坏了（异常），它之后的所有菜全部倒掉重来，客人看到的菜序始终和点单一致。</span></p><p><span class="marginnote">ROB 是环形队列：分配在尾，提交在头。头指令未完成则整核不能提交后面已完成的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取指/译码后，每条指令在 ROB 占一项，记下 PC、目标寄存器、结果槽。操作数就绪则发到功能单元，完成时写回 ROB 项，不直接写架构堆。ROB 头若已完成且无异常，把结果写入架构寄存器或让 store 对 cache 可见，然后释放该项。</p>',10)),(o(),t(i,null,{default:e(()=>[B(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIS%5B%22%E6%8C%89%E5%BA%8F%E5%88%86%E9%85%8D%20ROB%22%5D%20--%3E%20EX%5B%22%E5%B0%B1%E7%BB%AA%E5%88%99%E4%B9%B1%E5%BA%8F%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20ROB%5B%22%E7%BB%93%E6%9E%9C%E5%86%99%E5%85%A5%20ROB%20%E9%A1%B9%22%5D%0A%20%20ROB%20--%3E%20COM%5B%22%E9%98%9F%E5%A4%B4%E5%AE%8C%E6%88%90%E5%88%99%E6%8F%90%E4%BA%A4%22%5D%0A%20%20ROB%20--%3E%20FLUSH%5B%22%E5%BC%82%E5%B8%B8%EF%BC%9A%E5%86%B2%E5%88%B7%E5%A4%B4%E4%B9%8B%E5%90%8E%E5%85%A8%E9%83%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">数字实例：ALU 运算约 1 拍，而访存缺失的 load 要一两百拍。顺序核里后一条独立 <code>add</code> 只能陪等一整段；乱序核则趁这段时间把窗口里几百条（现代 ROB 约数百项）无关指令全部算完——这就是乱序换来的停顿吸收能力。</span></p><p>store 在提交前不得让 cache 对别的核或 DMA 可见，否则无法精确收回。<a href="/cs/coherence-intro">一致性问题引入</a>在这里约束提交：未提交写不是一致性协议要传播的写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>程序员仍看见顺序 ISA。CPI 的停顿项从「相关就停发射」变成「窗口填不满、提交头堵住」。窗口大小受 ROB 项数、物理寄存器数限制。误预测仍冲刷：ROB 里预测路径上的项全部丢弃，与精确异常同一套回滚。</p><p>重命名把架构寄存器映射到 ROB 项或物理寄存器，消除 WAR/WAW，只留 RAW。映射表随提交更新，随冲刷恢复。</p><p>重命名为什么能「无中生有」地消灭假相关：</p>',6)),(o(),t(i,null,{default:e(()=>[B(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20I1%5B%22i1%20(%E5%B9%B4%E9%95%BF)%3A%20%E5%86%99%20x1%22%5D%20--%3E%20REN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%3A%20%E5%90%84%E9%85%8D%E4%B8%80%E4%B8%AA%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20I2%5B%22i2%20(%E5%B9%B4%E8%BD%BB)%3A%20%E4%B9%9F%E5%86%99%20x1%22%5D%20--%3E%20REN%0A%20%20REN%20--%3E%20P1%5B%22i1%20%E5%86%99%20P3%22%5D%0A%20%20REN%20--%3E%20P2%5B%22i2%20%E5%86%99%20P7%22%5D%0A%20%20P1%20--%3E%20NO%5B%22WAW%2FWAR%20%E5%81%87%E7%9B%B8%E5%85%B3%E6%B6%88%E5%A4%B1%22%5D%0A%20%20P2%20--%3E%20NO%0A%20%20RAW%5B%22i3%20%E8%AF%BB%20i2%20%E7%9A%84%E7%BB%93%E6%9E%9C%22%5D%20--%3E%7C%22%E7%9C%9F%E7%9B%B8%E5%85%B3%20RAW%20%E4%BB%8D%E5%9C%A8%22%7C%20P2%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：初学者以为「乱序执行」会让程序行为变得不确定。实际上架构状态只在 ROB 头按程序序提交，单核上外部可见的结果与按序执行一字不差——乱序只是流水线内部的加速手段，不是语义改变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画保留站和公共数据总线，不比较 CDC 6600 记分牌。那是 Tomasulo 课用 1967 年的算法把唤醒说清。也不引入多核可见性：提交后的 store 才进入一致性世界。</p><p>后课默认：谈到乱序核，执行可以超前，架构状态只在 ROB 头提交时改变。精确异常 = 冲刷头之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乱序执行，按序提交；ROB 托住未提交结果。</li><li>异常与误预测靠冲刷 ROB 恢复精确状态。</li><li>唤醒与广播的经典算法是下一课 Tomasulo。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 乱序与 ROB。</li></ul>',6))])}const O=l(d,[["render",p]]);export{D as __pageData,O as default};
